import sys

edges = {divmod(int(token), 10) for token in sys.stdin.read().split()}
adj = {v: set() for edge in edges for v in edge}
for u, v in edges:
    adj[u].add(v)
answer = 0
for a in adj:
    for b in adj[a]:
        if b == a:
            continue
        for c in adj[b]:
            if c != a and c != b:
                answer += 100 * a + 10 * b + c
print(answer)
